# Check diagonal patterns, row/col sums, etc.
def analyze_grid(grid):
    rows = len(grid)
    cols = len(grid[0])

    # Check horizontal sequences
    print("Horizontal sequences:")
    for i, row in enumerate(grid):
        seqs = []
        curr = None
        for j, val in enumerate(row):
            if val == 0:
                if curr is not None:
                    seqs.append((curr[0], curr[1], curr[2]))
                    curr = None
            else:
                if curr is None:
                    curr = [row[j]]
                else:
                    curr.append(row[j])
        if curr:
            seqs.append(tuple(curr))
        if seqs:
            print(f"  Row {i}: {seqs}")

    # Check vertical sequences
    print("\nVertical sequences:")
    for j in range(cols):
        col = [grid[i][j] for i in range(rows)]
        seqs = []
        curr = None
        for i, val in enumerate(col):
            if val == 0:
                if curr is not None:
                    seqs.append((curr[0], curr[1], curr[2]))
                    curr = None
            else:
                if curr is None:
                    curr = [val]
                else:
                    curr.append(val)
        if curr:
            seqs.append(tuple(curr))
        if seqs:
            print(f"  Col {j}: {seqs}")

analyze_grid(test_grid)

